<?= $this->extend('layout') ?><?= $this->section('content') ?><h1>Products</h1><a class="button" href="<?= site_url('products/new') ?>">Add Product</a><section class="card"><table><thead><tr><th>Image</th><th>Name</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><?php if($product['image']): ?><img class="thumb" src="<?= base_url('uploads/products/'.rawurlencode($product['image'])) ?>" alt="<?= esc($product['name']) ?>"><?php endif ?></td><td><?= esc($product['name']) ?></td><td>₱<?= esc($product['price']) ?></td><td><?= esc($product['stock_quantity']) ?></td><td><a href="<?= site_url('products/'.$product['id'].'/edit') ?>">Edit</a> <form class="inline" method="post" action="<?= site_url('products/'.$product['id'].'/archive') ?>"><?= csrf_field() ?><button class="danger">Archive</button></form></td></tr><?php endforeach ?></tbody></table></section><?= $this->endSection() ?>
